#include <stdio.h>
#include <string.h>

int dp[100001];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    memset(dp, 0x3f, sizeof(dp));
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        int t = i;
        while (t > 0) {
            int d = t % 10;
            if (d > 0 && dp[i - d] + 1 < dp[i])
                dp[i] = dp[i - d] + 1;
            t /= 10;
        }
    }

    printf("%d\n", dp[n]);
    return 0;
}
